import React, { useState, useEffect, useCallback } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import toast from 'react-hot-toast';
import { FiTrash2, FiEye, FiPlus, FiX, FiMapPin, FiPhone, FiUser } from 'react-icons/fi';

const SellerDashboard = () => {
    const { user } = useAuth();
    const [products, setProducts] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [stats, setStats] = useState({ totalProducts: 0 });
    
    // Estado do modal
    const [modalOpen, setModalOpen] = useState(false);
    const [selectedProduct, setSelectedProduct] = useState(null);
    const [showContact, setShowContact] = useState(false);
    const [currentPhotoIndex, setCurrentPhotoIndex] = useState(0);

    const fetchProducts = useCallback(async () => {
        try {
            setLoading(true);
            setError('');
            const response = await api.get(`/products/seller/${user.id}`);
            if (response.data.success) {
                setProducts(response.data.products);
                setStats({ totalProducts: response.data.products.length });
            } else {
                setError('Erro ao carregar produtos');
            }
        } catch (error) {
            console.error('Erro detalhado:', error);
            setError(error.response?.data?.error || 'Erro ao carregar anúncios');
            toast.error('Erro ao carregar anúncios');
        } finally {
            setLoading(false);
        }
    }, [user.id]);

    useEffect(() => {
        fetchProducts();
    }, [fetchProducts]);

    const deleteProduct = async (id) => {
        if (!window.confirm('Tem certeza que deseja remover este anúncio?')) return;
        try {
            await api.delete(`/products/${id}`);
            toast.success('Anúncio removido com sucesso!');
            fetchProducts();
        } catch (error) {
            toast.error('Erro ao remover anúncio');
        }
    };

    const openModal = (product) => {
        setSelectedProduct(product);
        setCurrentPhotoIndex(0);
        setShowContact(false);
        setModalOpen(true);
    };

    const closeModal = () => {
        setModalOpen(false);
        setSelectedProduct(null);
        setShowContact(false);
    };

    const getCategoryIcon = (category) => {
        const icons = { telemovel: '📱', laptop: '💻', console: '🎮', tablet: '📟' };
        return icons[category] || '📦';
    };

    const getStatusBadge = (status) => {
        if (status === 'active') {
            return <span className="px-2 py-1 text-xs rounded-full bg-green-100 text-green-600">Ativo</span>;
        }
        return <span className="px-2 py-1 text-xs rounded-full bg-gray-100 text-gray-600">Inativo</span>;
    };

    const getContactMethodIcon = (method) => {
        if (method === 'whatsapp') return '💚 WhatsApp';
        if (method === 'call') return '📞 Ligação';
        return '💚 WhatsApp / 📞 Ligação';
    };

    const handleBackdropClick = (e) => {
        if (e.target === e.currentTarget) closeModal();
    };

    if (loading) {
        return (
            <div className="flex justify-center items-center h-64">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
            </div>
        );
    }

    if (error) {
        return (
            <div className="bg-red-50 border border-red-200 rounded-xl p-8 text-center">
                <p className="text-red-600 mb-4">{error}</p>
                <button 
                    onClick={fetchProducts}
                    className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700"
                >
                    Tentar novamente
                </button>
            </div>
        );
    }

    return (
        <div>
            <div className="bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-2xl p-6 mb-8">
                <h1 className="text-2xl font-bold mb-2">Meu Painel</h1>
                <p className="opacity-90">Gerencie seus anúncios</p>
            </div>

            <div className="bg-white rounded-xl shadow-md p-6 text-center mb-8">
                <div className="text-3xl font-bold text-blue-600 mb-2">{stats.totalProducts}</div>
                <div className="text-gray-600">Total de Anúncios</div>
            </div>

            <div className="flex justify-between items-center mb-6">
                <h2 className="text-xl font-bold">Meus Anúncios</h2>
                <Link to="/create-product" className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition flex items-center gap-2">
                    <FiPlus /> Novo Anúncio
                </Link>
            </div>

            {products.length === 0 ? (
                <div className="bg-white rounded-xl shadow-md p-12 text-center">
                    <p className="text-gray-500 mb-4">Você ainda não tem anúncios.</p>
                    <Link to="/create-product" className="text-blue-600 hover:underline">Criar meu primeiro anúncio</Link>
                </div>
            ) : (
                <div className="bg-white rounded-xl shadow-md overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead className="bg-gray-50">
                                <tr>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Produto</th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Preço</th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Estado</th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Ações</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-200">
                                {products.map(product => (
                                    <tr key={product.id} className="hover:bg-gray-50">
                                        <td className="px-6 py-4">
                                            <div className="flex items-center gap-3">
                                                {product.photos && product.photos[0] ? (
                                                    <img 
                                                        src={`http://localhost:3001${product.photos[0]}`} 
                                                        alt={product.title} 
                                                        className="w-12 h-12 object-cover rounded-lg" 
                                                    />
                                                ) : (
                                                    <div className="w-12 h-12 bg-gray-100 rounded-lg flex items-center justify-center text-2xl">
                                                        {getCategoryIcon(product.category)}
                                                    </div>
                                                )}
                                                <div>
                                                    <div className="font-medium text-gray-900">{product.title}</div>
                                                    <div className="text-sm text-gray-500">{product.category}</div>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 font-semibold text-blue-600">{product.price.toLocaleString()} Kz</td>
                                        <td className="px-6 py-4">
                                            <span className={`px-2 py-1 text-xs rounded-full ${product.condition === 'novo' ? 'bg-green-100 text-green-600' : 'bg-yellow-100 text-yellow-600'}`}>
                                                {product.condition === 'novo' ? 'Novo' : 'Semi-novo'}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4">{getStatusBadge(product.status)}</td>
                                        <td className="px-6 py-4">
                                            <div className="flex gap-2">
                                                <button 
                                                    onClick={() => openModal(product)}
                                                    className="text-blue-600 hover:text-blue-800 transition"
                                                    title="Visualizar"
                                                >
                                                    <FiEye size={18} />
                                                </button>
                                                <button 
                                                    onClick={() => deleteProduct(product.id)} 
                                                    className="text-red-600 hover:text-red-800 transition"
                                                    title="Remover"
                                                >
                                                    <FiTrash2 size={18} />
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}

            {/* Modal de detalhes do produto */}
            {modalOpen && selectedProduct && (
                <div 
                    className="fixed inset-0 bg-black bg-opacity-50 backdrop-blur-sm flex items-center justify-center z-[1000] p-2 sm:p-4"
                    onClick={handleBackdropClick}
                >
                    <div className="bg-white rounded-2xl w-full max-w-[95%] sm:max-w-[90%] md:max-w-2xl max-h-[95vh] overflow-y-auto shadow-2xl">
                        <div className="sticky top-0 bg-white border-b p-3 sm:p-4 flex justify-between items-center rounded-t-2xl">
                            <h2 className="text-base sm:text-lg font-semibold text-gray-800">Detalhes do Produto</h2>
                            <button onClick={closeModal} className="p-1.5 sm:p-2 hover:bg-gray-100 rounded-full transition">
                                <FiX size={18} />
                            </button>
                        </div>

                        <div className="p-4 sm:p-5">
                            {/* Imagem */}
                            <div className="bg-gray-100 rounded-xl p-3 sm:p-4 flex justify-center items-center mb-4 h-48 sm:h-56 md:h-64">
                                {selectedProduct.photos && selectedProduct.photos[0] ? (
                                    <img 
                                        src={`http://localhost:3001${selectedProduct.photos[currentPhotoIndex]}`} 
                                        alt={selectedProduct.title} 
                                        className="max-w-full max-h-full object-contain" 
                                    />
                                ) : (
                                    <div className="text-5xl sm:text-6xl">{getCategoryIcon(selectedProduct.category)}</div>
                                )}
                            </div>

                            {/* Miniaturas */}
                            {selectedProduct.photos && selectedProduct.photos.length > 1 && (
                                <div className="flex gap-1.5 sm:gap-2 mb-4 sm:mb-5 overflow-x-auto pb-2">
                                    {selectedProduct.photos.map((photo, idx) => (
                                        <button
                                            key={idx}
                                            onClick={() => setCurrentPhotoIndex(idx)}
                                            className={`w-12 h-12 sm:w-14 sm:h-14 rounded-lg overflow-hidden border-2 flex-shrink-0 ${
                                                currentPhotoIndex === idx ? 'border-blue-500' : 'border-gray-200'
                                            }`}
                                        >
                                            <img src={`http://localhost:3001${photo}`} alt="" className="w-full h-full object-cover" />
                                        </button>
                                    ))}
                                </div>
                            )}

                            <h3 className="text-lg sm:text-xl font-bold text-gray-800 mb-1">{selectedProduct.title}</h3>
                            
                            <div className="flex items-center gap-2 mb-3">
                                <span className={`px-2 py-1 rounded-full text-xs font-semibold ${
                                    selectedProduct.condition === 'novo' ? 'bg-green-100 text-green-600' : 'bg-yellow-100 text-yellow-600'
                                }`}>
                                    {selectedProduct.condition === 'novo' ? 'Novo' : 'Semi-novo'}
                                </span>
                                <span className="text-xs text-gray-400">{selectedProduct.category}</span>
                            </div>

                            <p className="text-xl sm:text-2xl font-bold text-blue-600 mb-4">
                                {selectedProduct.price.toLocaleString()} Kz
                            </p>

                            <div className="border-t border-gray-100 pt-4 mb-4">
                                <p className="text-gray-700 text-sm leading-relaxed">{selectedProduct.description}</p>
                            </div>

                            <div className="space-y-2 mb-5 text-sm">
                                <div className="flex items-center text-gray-500">
                                    <FiMapPin className="mr-2 text-gray-400" size={14} />
                                    <span>{selectedProduct.location}</span>
                                </div>
                                <div className="flex items-center text-gray-500">
                                    <FiUser className="mr-2 text-gray-400" size={14} />
                                    <span>{selectedProduct.sellerName}</span>
                                </div>
                            </div>

                            {user && selectedProduct.sellerId !== user.id && (
                                <>
                                    {showContact ? (
                                        <div className="bg-green-50 rounded-xl p-3 sm:p-4 border border-green-200">
                                            <p className="font-medium text-green-700 mb-1">{getContactMethodIcon(selectedProduct.contactMethod)}</p>
                                            <p className="text-base sm:text-lg font-bold text-green-700">{selectedProduct.contactNumber}</p>
                                            {selectedProduct.contactHours && (
                                                <p className="text-xs text-green-600 mt-1">Horário: {selectedProduct.contactHours}</p>
                                            )}
                                        </div>
                                    ) : (
                                        <button
                                            onClick={() => setShowContact(true)}
                                            className="w-full bg-blue-600 text-white py-2.5 rounded-lg font-medium hover:bg-blue-700 transition"
                                        >
                                            Ver número do vendedor
                                        </button>
                                    )}
                                </>
                            )}

                            {user && selectedProduct.sellerId === user.id && (
                                <div className="bg-blue-50 rounded-xl p-3 border border-blue-200">
                                    <p className="text-blue-600 font-medium">📌 Este é seu anúncio</p>
                                    <p className="text-xs text-blue-600 mt-1">
                                        {getContactMethodIcon(selectedProduct.contactMethod)}: {selectedProduct.contactNumber}
                                    </p>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default SellerDashboard;
